"""The shared detection-rule interface (provided - students do not edit this file).

A rule is a small class:

    class MyRule(BaseRule):
        rule_id  = "my_rule"                 # unique, snake_case
        name     = "Human readable name"
        category = "Reconnaissance"          # used to group rules in the dashboard
        description = "One sentence about what the rule looks for."
        defaults = {"threshold": 100}        # every tunable number lives here
        limitations = "What this rule cannot see."
        false_positives = "Ordinary activity that can look like this."

        def detect(self, context):           # context: see engine/default_rules/__init__.py
            return [self.finding(...)]       # a list (empty if nothing was found)

Thresholds can be overridden per instance: ``MyRule(threshold=50)`` - unknown names raise
``TypeError`` so typos are caught instead of silently ignored.

FINDING FORMAT (what ``self.finding()`` returns; the report builder and the dashboard rely on it)
    rule_id, name, category            who raised it
    severity        "High" | "Medium" | "Low" | "Informational"   - potential impact if it is real
    confidence      "High" | "Medium" | "Low"                       - how strongly the evidence supports it
    classification  "observed"  a fact directly visible in the capture (e.g. plaintext login seen)
                    "indicator" a suspicious pattern that needs a human to judge
                    "inferred"  an attack type inferred from several indicators
    summary         one sentence
    explanation     WHY it was flagged (the logic, in plain English)
    evidence        list of short factual strings
    stats           dict of numbers (counts, rates, ratios)
    source_ips, destination_ips, source_ports, destination_ports, protocol
    first_seen, last_seen (epoch seconds or None), window_seconds
    packet_numbers (max 100, 1-based frames), packet_count (true total)
    recommendation, limitations, false_positive_risk, thresholds
"""
from __future__ import annotations

from typing import Any, Dict, Iterable, List, Optional

from engine.default_rules.redaction import redact_text

SEVERITIES = ("High", "Medium", "Low", "Informational")
CONFIDENCES = ("High", "Medium", "Low")
CLASSIFICATIONS = ("observed", "indicator", "inferred")
MAX_FRAMES_PER_FINDING = 100


class BaseRule:
    rule_id = "base_rule"
    name = "Base rule"
    category = "General"
    description = ""
    defaults: Dict[str, Any] = {}
    limitations = ""
    false_positives = ""

    def __init__(self, **overrides: Any):
        unknown = set(overrides) - set(self.defaults)
        if unknown:
            raise TypeError(f"{self.__class__.__name__}: unknown parameter(s) {sorted(unknown)}; "
                            f"valid parameters are {sorted(self.defaults)}")
        self.params: Dict[str, Any] = {**self.defaults, **overrides}

    def detect(self, context: dict) -> List[dict]:        # pragma: no cover - interface
        raise NotImplementedError

    # ------------------------------------------------------------------ helpers
    def finding(self, *, summary: str, severity: str, confidence: str,
                classification: str = "indicator", explanation: str = "",
                evidence: Iterable[str] = (), stats: Optional[dict] = None,
                source_ips: Iterable[str] = (), destination_ips: Iterable[str] = (),
                source_ports: Iterable[int] = (), destination_ports: Iterable[int] = (),
                protocol: Optional[str] = None, first_seen: Optional[float] = None,
                last_seen: Optional[float] = None, window_seconds: Optional[float] = None,
                packet_numbers: Iterable[int] = (), recommendation: str = "",
                limitations: Optional[str] = None, title: Optional[str] = None) -> dict:
        if severity not in SEVERITIES:
            raise ValueError(f"severity must be one of {SEVERITIES}, not {severity!r}")
        if confidence not in CONFIDENCES:
            raise ValueError(f"confidence must be one of {CONFIDENCES}, not {confidence!r}")
        if classification not in CLASSIFICATIONS:
            raise ValueError(f"classification must be one of {CLASSIFICATIONS}, not {classification!r}")
        frames = sorted({int(n) for n in packet_numbers if n is not None})
        src = list(dict.fromkeys(source_ips))
        dst = list(dict.fromkeys(destination_ips))
        return {
            "rule_id": self.rule_id, "name": title or self.name, "category": self.category,
            "severity": severity, "confidence": confidence, "classification": classification,
            "summary": redact_text(summary), "explanation": redact_text(explanation),
            "evidence": [redact_text(str(e)) for e in evidence],
            "stats": dict(stats or {}),
            "source_ips": src[:20], "destination_ips": dst[:20],
            "source_ip": src[0] if src else None, "destination_ip": dst[0] if dst else None,
            "source_ports": sorted({int(p) for p in source_ports})[:30],
            "destination_ports": sorted({int(p) for p in destination_ports})[:30],
            "protocol": protocol, "first_seen": first_seen, "last_seen": last_seen,
            "window_seconds": window_seconds,
            "packet_numbers": frames[:MAX_FRAMES_PER_FINDING], "packet_count": len(frames),
            "recommendation": recommendation,
            "limitations": limitations if limitations is not None else self.limitations,
            "false_positive_risk": self.false_positives,
            "thresholds": dict(self.params),
        }

    def info(self) -> dict:
        return {"rule_id": self.rule_id, "name": self.name, "category": self.category,
                "description": self.description, "thresholds": dict(self.params),
                "limitations": self.limitations, "false_positive_risk": self.false_positives}
